prts.feedbackvariables:
user_ans: sort(listify(setify(ans1)));
leng:length(user_ans);
ss:0;
for j:1 while j<=leng do ss:ss+product(abs(user_ans[j]-ta[i]),i,1,2);
for i:1 while i<=2 do ss:ss+product(abs(user_ans[j]-ta[i]),j,1,leng);
cor:is(ss>=0) and (ss<=0);
is_list: listp(ans1);
ss1:product(abs(user_ans[j]-%e),j,1,leng);
ss2:product(abs(user_ans[j]+1/%e),j,1,leng);
ss3:product(abs(user_ans[j]+%e),j,1,leng);
ss4:product(abs(user_ans[j]-1/%e),j,1,leng);
is_partial_a:is(ss1>=0) and (ss1<=0);
is_partial_b:is(ss2>=0) and (ss2<=0);
is_partial_c:is(ss3>=0) and (ss3<=0);
